#!/data/data/com.termux/files/usr/bin/bash
# Repl live procedural horse locomotion v0.6.40: Termux Git source only.
# Canonical GLB mutation forbidden. Original six GLB clips preserved.
set -Eeuo pipefail
CAMPAIGN=REPL_HORSE_PROCEDURAL_CONTROLLER_v0.6.40
printf 'CAMPAIGN=%s\nLANE=ANDROID_TERMUX_GIT_SOURCE_ONLY\nCANONICAL_MODEL_MUTATION=FORBIDDEN\n' "$CAMPAIGN"
command -v python3 >/dev/null || { echo 'BLOCKED:PYTHON3_MISSING'; exit 2; }
command -v git >/dev/null || { echo 'BLOCKED:GIT_MISSING'; exit 2; }
command -v sha256sum >/dev/null || { echo 'BLOCKED:SHA256SUM_MISSING'; exit 2; }
export REPL_ENTRY_SCRIPT="$(readlink -f "$0")"
printf 'LAUNCHER_SHA256=%s\n' "$(sha256sum "$REPL_ENTRY_SCRIPT" | cut -d' ' -f1)"
T="$(mktemp -d "${TMPDIR:-/tmp}/repl-procedural-40-XXXXXXXX")"
trap 'rm -rf "$T"' EXIT
export REPL_PAYLOAD="$T"
python3 - <<'REPL_PACKET_BOOT'
